package app.prismkeys;
import android.inputmethodservice.InputMethodService;
import android.text.InputType;
import android.view.View;
import android.view.inputmethod.*;
import android.webkit.*;
import org.json.JSONObject;

/** Uses the supplied Prism HTML keyboard. Edits are accepted only against a matching field snapshot. */
public class PrismIME extends InputMethodService {
 static PrismIME active;static void hideForHandAction(){if(active!=null&&active.web!=null)active.web.post(()->{if(active!=null)active.requestHideSelf(0);});}
 WebView web;String snapshot="";boolean loaded=false,blocked=false;int expected=-1;
 public View onCreateInputView(){PrismRuntime.ensure(this);PrismRuntime.startHover(this);web=new WebView(this);MainActivity.configure(web);web.getSettings().setDefaultFontSize(14);web.addJavascriptInterface(new Bridge(),"PrismAndroid");web.setWebViewClient(new WebViewClient(){public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return MainActivity.asset(v,r);}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){if(MainActivity.local(r.getUrl().toString()))return false;if(r.isForMainFrame()&&"https".equals(r.getUrl().getScheme())){try{android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_VIEW,r.getUrl());i.addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);}catch(Exception e){}}return true;}public void onPageFinished(WebView v,String url){if(!MainActivity.local(url))return;loaded=true;PrismRuntime.connect(v);v.evaluateJavascript("(()=>{window.prismNative=true;enableNativeKeyboardUI();document.getElementById('androidHands').hidden=false;document.getElementById('androidHands').onclick=()=>PrismAndroid.hands();document.getElementById('previewFrame').setAttribute('sandbox','');const old=setText;setText=function(v){old(v);PrismAndroid.update(T.value,T.selectionStart);};T.addEventListener('input',()=>PrismAndroid.update(T.value,T.selectionStart));T.addEventListener('select',()=>PrismAndroid.cursor(T.selectionStart,T.selectionEnd));document.getElementById('bU').addEventListener('click',()=>PrismAndroid.update(T.value,T.selectionStart));document.getElementById('dictate').onclick=()=>PrismAndroid.voice();document.getElementById('bK').onclick=()=>PrismAndroid.copy(T.value);document.getElementById('speak').onclick=()=>PrismAndroid.speak(T.value);document.getElementById('stopVoice').onclick=()=>PrismAndroid.stopVoice();})()",null);capture();}});web.setLayoutParams(new android.widget.LinearLayout.LayoutParams(-1,(int)(Math.min(330,getResources().getDisplayMetrics().heightPixels/getResources().getDisplayMetrics().density*0.48f)*getResources().getDisplayMetrics().density)));web.loadUrl(PrismRuntime.URL);return web;}
 boolean sensitive(EditorInfo info){if(info==null)return true;int v=info.inputType&InputType.TYPE_MASK_VARIATION;int cls=info.inputType&InputType.TYPE_MASK_CLASS;return (cls==InputType.TYPE_CLASS_TEXT&&(v==InputType.TYPE_TEXT_VARIATION_PASSWORD||v==InputType.TYPE_TEXT_VARIATION_WEB_PASSWORD||v==InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD))||(cls==InputType.TYPE_CLASS_NUMBER&&v==InputType.TYPE_NUMBER_VARIATION_PASSWORD);}
 public void onStartInput(EditorInfo info,boolean restarting){super.onStartInput(info,restarting);blocked=sensitive(info);expected=-1;capture();}
 public void onStartInputView(EditorInfo info,boolean restarting){super.onStartInputView(info,restarting);blocked=sensitive(info);capture();}
 ExtractedText field(){InputConnection c=getCurrentInputConnection();if(c==null)return null;ExtractedTextRequest req=new ExtractedTextRequest();req.hintMaxChars=12000;req.hintMaxLines=100;return c.getExtractedText(req,0);}
 void capture(){if(web==null||!loaded)return;ExtractedText e=blocked?null:field();boolean valid=e!=null&&e.text!=null&&e.startOffset==0&&e.partialStartOffset<0&&e.text.length()<=12000;blocked=blocked||!valid;snapshot=blocked?"":e.text.toString();int cursor=blocked?0:e.selectionStart;expected=cursor;web.evaluateJavascript("T.value="+JSONObject.quote(snapshot)+";hist=[];T.setSelectionRange("+cursor+","+(blocked?0:e.selectionEnd)+");render();T.disabled="+blocked+";document.getElementById('kb').style.pointerEvents="+JSONObject.quote(blocked?"none":"auto")+";"+(blocked?"toast('Private or unsupported field · switch keyboard using Android keyboard picker');":""),null);}
 public void onUpdateSelection(int oldStart,int oldEnd,int start,int end,int candidatesStart,int candidatesEnd){super.onUpdateSelection(oldStart,oldEnd,start,end,candidatesStart,candidatesEnd);if(start!=expected||end!=expected)capture();}
 void showDialog(android.app.AlertDialog dialog){android.view.Window w=dialog.getWindow();android.view.WindowManager.LayoutParams p=w.getAttributes();p.token=getWindow().getWindow().getAttributes().token;w.setAttributes(p);w.setType(android.view.WindowManager.LayoutParams.TYPE_APPLICATION_ATTACHED_DIALOG);dialog.show();}
 final class Bridge {
  @JavascriptInterface public void chooseKeyboard(){web.post(()->((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showInputMethodPicker());}

  @JavascriptInterface public void hands(){web.post(()->{
   String[] options={"Back","Home","Recent apps","Open app by package name","Enable device controls"};
   showDialog(new android.app.AlertDialog.Builder(PrismIME.this).setTitle("Android hands").setItems(options,(dialog,which)->{
    if(which<3){int[] actions={android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK,android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_HOME,android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_RECENTS};if(!HandsService.action(actions[which]))web.evaluateJavascript("toast('Enable Prism device controls in Android accessibility settings');",null);}
    if(which==3){android.widget.EditText input=new android.widget.EditText(PrismIME.this);input.setHint("e.g. com.android.settings");showDialog(new android.app.AlertDialog.Builder(PrismIME.this).setTitle("Open installed app").setView(input).setPositiveButton("Open",(d,w)->{android.content.Intent intent=getPackageManager().getLaunchIntentForPackage(input.getText().toString().trim());if(intent!=null){intent.addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(intent);}else web.evaluateJavascript("toast('App unavailable or not visible to Prism');",null);}).setNegativeButton("Cancel",null).create());}
    if(which==4){android.content.Intent intent=new android.content.Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS);intent.addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(intent);}
   }).create());
  });}

  @JavascriptInterface public void update(String text,int cursor){if(web==null)return;web.post(()->{if(blocked)return;InputConnection c=getCurrentInputConnection();ExtractedText e=field();if(c==null||e==null||!snapshot.contentEquals(e.text)){capture();return;}int prefix=0;while(prefix<snapshot.length()&&prefix<text.length()&&snapshot.charAt(prefix)==text.charAt(prefix))prefix++;int suffix=0;while(suffix<snapshot.length()-prefix&&suffix<text.length()-prefix&&snapshot.charAt(snapshot.length()-1-suffix)==text.charAt(text.length()-1-suffix))suffix++;expected=Math.max(0,Math.min(cursor,text.length()));c.beginBatchEdit();c.setSelection(prefix,snapshot.length()-suffix);c.commitText(text.substring(prefix,text.length()-suffix),1);c.setSelection(expected,expected);c.endBatchEdit();snapshot=text;});}
  @JavascriptInterface public void cursor(int start,int end){web.post(()->{if(!blocked&&start>=0&&end>=start&&end<=snapshot.length()){expected=start;InputConnection c=getCurrentInputConnection();if(c!=null)c.setSelection(start,end);}});}
  @JavascriptInterface public void copy(String text){web.post(()->((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(android.content.ClipData.newPlainText("Prism Keys",text)));}
  @JavascriptInterface public void voice(){web.post(()->{android.content.Intent i=new android.content.Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK);try{startActivity(i);}catch(Exception e){web.evaluateJavascript("toast('Use your Android voice keyboard for dictation');",null);}});}
  @JavascriptInterface public void speak(String text){web.post(()->{if(tts!=null&&ttsReady)tts.speak(text,android.speech.tts.TextToSpeech.QUEUE_FLUSH,null,"prism");});}
  @JavascriptInterface public void stopVoice(){web.post(()->{if(tts!=null)tts.stop();});}
 }
 android.speech.tts.TextToSpeech tts;boolean ttsReady=false;
 public void onCreate(){super.onCreate();active=this;tts=new android.speech.tts.TextToSpeech(this,status->ttsReady=status==android.speech.tts.TextToSpeech.SUCCESS);}
 public void onDestroy(){active=null;if(tts!=null)tts.shutdown();if(web!=null)web.destroy();super.onDestroy();}
}
